import { Redo2, Trash2, Undo2 } from "lucide-react";
import { useState } from "react";

import { useEdit, useEditor, useSelection } from "@uberscene/editor";
import { knobsOf, SCHEMAS_BY_KIND } from "@uberscene/kit/schema";
import type { ActionInput } from "@uberscene/sdk";

import { type Access, fail, Group, NumberField, Row, TextField } from "./fields";
import { Typography } from "./typography";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";

/** Props the inspector leaves to other controls: timing (the timeline and the fields at the top), ids, children. */
const SKIP = new Set([
  "id",
  "start",
  "duration",
  "end",
  "in",
  "out",
  "anchor",
  "at",
  "offset",
  "after",
  "children",
  "text",
]);
/** Kinds `element/update` writes; any other element's props go through `source/setProp`. */
const UPDATABLE = new Set(["title", "shape", "svg", "sticker", "adjustment", "nested", "layer"]);

type Knob = ReturnType<typeof knobsOf>[number];
type Scalar = string | number | boolean;

const isScalar = (v: unknown): v is Scalar => ["string", "number", "boolean"].includes(typeof v);
const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/**
 * The selected element: its timing, its text, and every prop its schema lists, as fields. A change is one undoable
 * edit. Props written as an expression in the file are locked, and props bound to a value the file declares are shown
 * but not written; the field says which.
 */
export function Inspector({ className }: { className?: string }) {
  const { state } = useEditor();
  const [selected, select] = useSelection();
  const edit = useEdit();
  const [error, setError] = useState<string | null>(null);
  const run = (input: ActionInput) => setError(fail(edit.execute(input)));
  const item = selected ? state.items.get(selected) : undefined;
  const raw = (selected && state.tree.byId.get(selected)?.props) || {};
  const access = (prop: string): Access =>
    item?.lockedProps.includes(prop) ? "locked" : item && prop in item.boundProps ? "bound" : "literal";

  const writeProp = (key: string, value: unknown) => {
    if (!item) return;
    run(
      (key === "box"
        ? { type: "box/update", params: { id: item.id, box: value } }
        : UPDATABLE.has(item.kind)
          ? { type: "element/update", params: { id: item.id, props: { [key]: value } } }
          : { type: "source/setProp", params: { id: item.id, prop: key, value } }) as ActionInput,
    );
  };

  return (
    <div className={cn("flex h-full min-h-0 flex-col", className)} data-editor-inspector="">
      <div className="flex items-center gap-1 border-b p-2">
        <Button variant="ghost" size="sm" disabled={!edit.canUndo} onClick={() => setError(fail(edit.undo()))}>
          <Undo2 /> Undo
        </Button>
        <Button variant="ghost" size="sm" disabled={!edit.canRedo} onClick={() => setError(fail(edit.redo()))}>
          <Redo2 /> Redo
        </Button>
        {item && (
          <Button
            variant="ghost"
            size="icon"
            className="ml-auto text-destructive"
            aria-label="Delete"
            onClick={() => {
              run({ type: "element/remove", params: { id: item.id } });
              select(null);
            }}
          >
            <Trash2 />
          </Button>
        )}
      </div>
      <ScrollArea className="min-h-0 flex-1">
        {item ? (
          <div className="flex flex-col gap-4 p-3 text-sm">
            <div className="flex items-center gap-2">
              <Badge variant="secondary">{item.kind}</Badge>
              <span className="truncate font-mono text-xs text-muted-foreground">{item.id}</span>
            </div>
            <Group title="Timing">
              <Row label="Start" access={access("start")}>
                <NumberField
                  value={round(item.start)}
                  step={0.1}
                  disabled={access("start") !== "literal"}
                  onCommit={(v) =>
                    run({ type: "clip/move", params: { id: item.id, place: { start: Math.max(0, v) } } })
                  }
                />
              </Row>
              <Row label="Duration" access={access("duration")}>
                <NumberField
                  value={round(item.duration)}
                  step={0.1}
                  disabled={access("duration") !== "literal"}
                  onCommit={(v) =>
                    run({
                      type: "clip/trim",
                      params: { id: item.id, edge: "out", value: round(item.start + Math.max(0.05, v)) },
                    })
                  }
                />
              </Row>
            </Group>
            {item.kind === "title" && (
              <Group title="Text">
                <TextField
                  multiline
                  label="Text"
                  value={state.tree.byId.get(item.id)?.text ?? ""}
                  disabled={access("text") !== "literal"}
                  onCommit={(text) => run({ type: "text/setContent", params: { id: item.id, text } })}
                />
              </Group>
            )}
            {knobsOf(SCHEMAS_BY_KIND[item.kind], raw)
              .filter((k) => !SKIP.has(k.key))
              .map((k) => {
                // How text looks has a panel of its own, every property shown whether the file sets it or not.
                if (k.key === "style" && (item.kind === "title" || item.kind === "captions"))
                  return <Typography key={k.key} id={item.id} onError={setError} />;
                const value = raw[k.key] ?? k.value;
                // An object prop (style, box) is shown one level down, a field per key it holds.
                if (isObject(value))
                  return (
                    <Group key={k.key} title={k.description ?? k.key}>
                      {Object.entries(value)
                        .filter(([, v]) => isScalar(v))
                        .map(([sub, v]) => {
                          const a = access(k.key) === "literal" ? access(`${k.key}.${sub}`) : access(k.key);
                          return (
                            <Row key={sub} label={sub} access={a}>
                              <ScalarField
                                name={`${k.key}.${sub}`}
                                value={v as Scalar}
                                disabled={a !== "literal"}
                                onCommit={(next) =>
                                  writeProp(k.key, k.key === "box" ? { [sub]: next } : { ...value, [sub]: next })
                                }
                              />
                            </Row>
                          );
                        })}
                    </Group>
                  );
                if (k.kind === "other" && !isScalar(value)) return null;
                return (
                  <Row key={k.key} label={k.description ?? k.key} access={access(k.key)}>
                    <KnobField
                      knob={k}
                      value={value}
                      disabled={access(k.key) !== "literal"}
                      onCommit={(v) => writeProp(k.key, v)}
                    />
                  </Row>
                );
              })}
            {error && (
              <p className="text-destructive" role="alert">
                {error}
              </p>
            )}
          </div>
        ) : (
          <p className="p-3 text-sm text-muted-foreground">Select an element in the layers or on the timeline.</p>
        )}
      </ScrollArea>
    </div>
  );
}

const round = (n: number) => Math.round(n * 1000) / 1000;

function KnobField({
  knob,
  value,
  disabled,
  onCommit,
}: {
  knob: Knob;
  value: unknown;
  disabled: boolean;
  onCommit: (v: Scalar) => void;
}) {
  if (knob.kind === "choice" && knob.options)
    return (
      <Select
        value={value === undefined ? undefined : String(value)}
        disabled={disabled}
        onValueChange={(v) => {
          const option = knob.options?.find((o) => String(o) === v);
          if (option !== undefined) onCommit(option);
        }}
      >
        <SelectTrigger size="sm" aria-label={knob.key}>
          <SelectValue placeholder="Default" />
        </SelectTrigger>
        <SelectContent>
          {knob.options.map((o) => (
            <SelectItem key={String(o)} value={String(o)}>
              {String(o)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  if (knob.kind === "boolean")
    return <Switch aria-label={knob.key} checked={value === true} disabled={disabled} onCheckedChange={onCommit} />;
  if (knob.kind === "number")
    return (
      <NumberField
        name={knob.key}
        value={typeof value === "number" ? value : undefined}
        min={knob.min}
        max={knob.max}
        disabled={disabled}
        onCommit={onCommit}
      />
    );
  return (
    <ScalarField
      name={knob.key}
      value={isScalar(value) ? value : ""}
      color={knob.kind === "color"}
      disabled={disabled}
      onCommit={onCommit}
    />
  );
}

/** A field for a value whose type is known only from the value itself, as inside an object prop. */
function ScalarField({
  name,
  value,
  color,
  disabled,
  onCommit,
}: {
  name: string;
  value: Scalar;
  color?: boolean;
  disabled: boolean;
  onCommit: (v: Scalar) => void;
}) {
  if (typeof value === "number")
    return <NumberField name={name} value={value} disabled={disabled} onCommit={onCommit} />;
  if (typeof value === "boolean")
    return <Switch aria-label={name} checked={value} disabled={disabled} onCheckedChange={onCommit} />;
  const swatch = color || /colou?r|background|fill/i.test(name);
  return <TextField label={name} value={value} swatch={swatch} disabled={disabled} onCommit={onCommit} />;
}

import {
  AlignCenter,
  AlignJustify,
  AlignLeft,
  AlignRight,
  AlignVerticalJustifyCenter,
  AlignVerticalJustifyEnd,
  AlignVerticalJustifyStart,
  Italic,
  Strikethrough,
  Underline,
} from "lucide-react";
import type { ReactNode } from "react";

import { useEdit, useEditor } from "@uberscene/editor";
import { FONT_CATALOG, findFont } from "@uberscene/kit/schema";
import type { ActionInput } from "@uberscene/sdk";

import { type Access, ColorField, fail, Group, LockMark, NumberField, Row } from "./fields";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Toggle } from "@/components/ui/toggle";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";

type Look = Record<string, unknown>;
type Kind = "title" | "captions";

/** What each kind's `style` holds, in the order a designer reads a text panel. */
const KEYS: Record<Kind, ReadonlySet<string>> = {
  title: new Set([
    "preset",
    "font",
    "weight",
    "size",
    "lineHeight",
    "letterSpacing",
    "align",
    "valign",
    "italic",
    "decoration",
    "color",
    "background",
    "stroke",
    "shadow",
  ]),
  captions: new Set([
    "preset",
    "font",
    "weight",
    "size",
    "align",
    "color",
    "background",
    "stroke",
    "shadow",
    "highlight",
    "highlightBox",
    "upcoming",
  ]),
};
const WEIGHTS = [100, 200, 300, 400, 500, 600, 700, 800, 900];
const WEIGHT_NAMES: Record<number, string> = {
  100: "Thin",
  200: "Extra light",
  300: "Light",
  400: "Regular",
  500: "Medium",
  600: "Semibold",
  700: "Bold",
  800: "Extra bold",
  900: "Black",
};
const isLook = (v: unknown): v is Look => typeof v === "object" && v !== null && !Array.isArray(v);
const weightOf = (w: unknown): number => (w === "bold" ? 700 : w === "normal" ? 400 : typeof w === "number" ? w : 400);

/**
 * How a title's or the captions' text looks, as a design tool's text panel shows it: every property, set in the file
 * or not. Each field shows the value the text has now (its preset and the defaults included) and writes only the one
 * key it changes into the element's `style`, so a preset named there keeps applying to the rest.
 */
export function Typography({ id, onError }: { id: string; onError: (message: string | null) => void }) {
  const { state } = useEditor();
  const edit = useEdit();
  const item = state.items.get(id);
  if (!item || (item.kind !== "title" && item.kind !== "captions")) return null;
  const kind = item.kind as Kind;
  const has = (key: string) => KEYS[kind].has(key);
  // What the file writes (a preset name alone, an object, or nothing) and what the text looks like now.
  const rawStyle = state.tree.byId.get(id)?.props.style;
  const own: Look = typeof rawStyle === "string" ? { preset: rawStyle } : isLook(rawStyle) ? rawStyle : {};
  const now: Look = isLook(item.props.style) ? item.props.style : {};
  const access = (key: string): Access => {
    for (const path of ["style", `style.${key}`]) {
      if (item.lockedProps.includes(path)) return "locked";
      if (path in item.boundProps) return "bound";
    }
    return "literal";
  };
  const off = (key: string) => access(key) !== "literal";

  const write = (key: string, value: unknown) => {
    const next: Look = { ...own };
    if (value === undefined || value === "") delete next[key];
    else next[key] = value;
    const style = Object.keys(next).length === 0 ? undefined : next;
    const action =
      kind === "title"
        ? { type: "element/update", params: { id, props: { style: style ?? {} } } }
        : { type: "caption/setStyle", params: { captionsId: id, style } };
    onError(fail(edit.execute(action as ActionInput)));
  };
  /** A colour as it shows: a theme token resolved through the theme. */
  const shown = (v: unknown): string | undefined =>
    typeof v !== "string" ? undefined : v.startsWith("$") ? String(state.theme.tokens[v.slice(1)] ?? v) : v;

  const presets = Object.keys(state.theme.styles[kind === "title" ? "title" : "captions"] ?? {});
  const family = String(now.font ?? "Inter");
  const families = [...new Set([family, ...state.fonts.map((f) => f.family), ...FONT_CATALOG.map((f) => f.family)])];
  const weights = findFont(family)?.weights ?? WEIGHTS;
  const weight = weightOf(now.weight);
  const stroke = isLook(now.stroke) ? now.stroke : {};
  const shadow = isLook(now.shadow) ? now.shadow : {};
  const ownStroke = isLook(own.stroke) ? own.stroke : {};
  const ownShadow = isLook(own.shadow) ? own.shadow : {};

  return (
    <Group title="Typography">
      <div className="flex flex-col gap-2" data-editor-typography="">
        {presets.length > 0 && (
          <Row label="Preset" access={access("preset")}>
            <Select
              value={typeof own.preset === "string" ? own.preset : "none"}
              disabled={off("preset")}
              onValueChange={(v) => write("preset", v === "none" ? undefined : v)}
            >
              <SelectTrigger size="sm" aria-label="Preset" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">None</SelectItem>
                {presets.map((p) => (
                  <SelectItem key={p} value={p}>
                    {p}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Row>
        )}
        <Row label="Font" access={access("font")}>
          <Select value={family} disabled={off("font")} onValueChange={(v) => write("font", v)}>
            <SelectTrigger size="sm" aria-label="Font" className="w-full" style={{ fontFamily: family }}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {families.map((f) => (
                <SelectItem key={f} value={f} style={{ fontFamily: f }}>
                  {f}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Row>
        <Pair>
          <Cell label="Weight" access={access("weight")}>
            <Select value={String(weight)} disabled={off("weight")} onValueChange={(v) => write("weight", Number(v))}>
              <SelectTrigger size="sm" aria-label="Weight" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[...new Set([...weights, weight])]
                  .sort((a, b) => a - b)
                  .map((w) => (
                    <SelectItem key={w} value={String(w)}>
                      {WEIGHT_NAMES[w] ?? w} <span className="text-muted-foreground">{w}</span>
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
          </Cell>
          <Cell label="Size" access={access("size")}>
            <NumberField
              name="Size"
              value={typeof now.size === "number" ? now.size : undefined}
              min={1}
              max={1000}
              disabled={off("size")}
              onCommit={(v) => write("size", v)}
            />
          </Cell>
        </Pair>
        {has("lineHeight") && (
          <Pair>
            <Cell label="Line height" access={access("lineHeight")}>
              <NumberField
                name="Line height"
                value={typeof now.lineHeight === "number" ? now.lineHeight : undefined}
                step={0.05}
                min={0.1}
                max={10}
                disabled={off("lineHeight")}
                onCommit={(v) => write("lineHeight", v)}
              />
            </Cell>
            <Cell label="Letter spacing" access={access("letterSpacing")}>
              <NumberField
                name="Letter spacing"
                value={typeof now.letterSpacing === "number" ? now.letterSpacing : undefined}
                step={0.5}
                min={-100}
                max={100}
                disabled={off("letterSpacing")}
                onCommit={(v) => write("letterSpacing", v)}
              />
            </Cell>
          </Pair>
        )}
        <Row label="Align" access={access("align")}>
          <div className="flex items-center gap-1">
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              aria-label="Align"
              value={String(now.align ?? "center")}
              disabled={off("align")}
              onValueChange={(v) => v && write("align", v)}
            >
              <ToggleGroupItem value="left" aria-label="Align left">
                <AlignLeft />
              </ToggleGroupItem>
              <ToggleGroupItem value="center" aria-label="Align center">
                <AlignCenter />
              </ToggleGroupItem>
              <ToggleGroupItem value="right" aria-label="Align right">
                <AlignRight />
              </ToggleGroupItem>
              {kind === "title" && (
                <ToggleGroupItem value="justify" aria-label="Justify">
                  <AlignJustify />
                </ToggleGroupItem>
              )}
            </ToggleGroup>
          </div>
        </Row>
        {has("valign") && (
          <Row label="Vertical" access={access("valign")}>
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              aria-label="Vertical align"
              value={String(now.valign ?? "middle")}
              disabled={off("valign")}
              onValueChange={(v) => v && write("valign", v)}
            >
              <ToggleGroupItem value="top" aria-label="Top">
                <AlignVerticalJustifyStart />
              </ToggleGroupItem>
              <ToggleGroupItem value="middle" aria-label="Middle">
                <AlignVerticalJustifyCenter />
              </ToggleGroupItem>
              <ToggleGroupItem value="bottom" aria-label="Bottom">
                <AlignVerticalJustifyEnd />
              </ToggleGroupItem>
            </ToggleGroup>
          </Row>
        )}
        {has("decoration") && (
          <Row label="Decoration" access={access("decoration")}>
            <div className="flex items-center gap-1">
              <Toggle
                variant="outline"
                size="sm"
                aria-label="Italic"
                pressed={now.italic === true}
                disabled={off("italic")}
                onPressedChange={(p) => write("italic", p ? true : undefined)}
              >
                <Italic />
              </Toggle>
              <ToggleGroup
                type="single"
                variant="outline"
                size="sm"
                aria-label="Decoration"
                value={now.decoration && now.decoration !== "none" ? String(now.decoration) : ""}
                disabled={off("decoration")}
                onValueChange={(v) => write("decoration", v || undefined)}
              >
                <ToggleGroupItem value="underline" aria-label="Underline">
                  <Underline />
                </ToggleGroupItem>
                <ToggleGroupItem value="lineThrough" aria-label="Strikethrough">
                  <Strikethrough />
                </ToggleGroupItem>
                <ToggleGroupItem value="overline" aria-label="Overline">
                  <span className="text-xs leading-none font-semibold overline">O</span>
                </ToggleGroupItem>
              </ToggleGroup>
            </div>
          </Row>
        )}
        <Row label="Color" access={access("color")}>
          <ColorField
            label="Color"
            value={typeof own.color === "string" ? own.color : undefined}
            shown={shown(now.color)}
            disabled={off("color")}
            onCommit={(v) => write("color", v)}
          />
        </Row>
        <Row label="Background" access={access("background")}>
          <ColorField
            label="Background"
            value={typeof own.background === "string" ? own.background : undefined}
            shown={shown(now.background)}
            disabled={off("background")}
            onCommit={(v) => write("background", v)}
          />
        </Row>
        {(["highlight", "highlightBox", "upcoming"] as const).filter(has).map((key) => (
          <Row
            key={key}
            label={key === "highlightBox" ? "Highlight box" : key[0]?.toUpperCase() + key.slice(1)}
            access={access(key)}
          >
            <ColorField
              label={key}
              value={typeof own[key] === "string" ? (own[key] as string) : undefined}
              shown={shown(now[key])}
              disabled={off(key)}
              onCommit={(v) => write(key, v)}
            />
          </Row>
        ))}
        <Row label="Stroke" access={access("stroke")}>
          <div className="grid grid-cols-[1fr_4.5rem] gap-2">
            <ColorField
              label="Stroke color"
              value={typeof ownStroke.color === "string" ? ownStroke.color : undefined}
              shown={shown(stroke.color)}
              disabled={off("stroke")}
              onCommit={(v) => write("stroke", v ? { thickness: 2, ...ownStroke, color: v } : undefined)}
            />
            <NumberField
              name="Stroke thickness"
              value={typeof stroke.thickness === "number" ? stroke.thickness : undefined}
              min={0}
              max={100}
              disabled={off("stroke")}
              onCommit={(v) => write("stroke", { color: "#000000", ...ownStroke, thickness: v })}
            />
          </div>
        </Row>
        <Row label="Shadow" access={access("shadow")}>
          <div className="flex flex-col gap-2">
            <ColorField
              label="Shadow color"
              value={typeof ownShadow.color === "string" ? ownShadow.color : undefined}
              shown={shown(shadow.color)}
              disabled={off("shadow")}
              onCommit={(v) => write("shadow", v ? { blur: 8, y: 2, ...ownShadow, color: v } : undefined)}
            />
            <div className="grid grid-cols-3 gap-2">
              {(["blur", "x", "y"] as const).map((k) => (
                <NumberField
                  key={k}
                  name={`Shadow ${k}`}
                  value={typeof shadow[k] === "number" ? (shadow[k] as number) : undefined}
                  disabled={off("shadow")}
                  onCommit={(v) => write("shadow", { color: "#000000", ...ownShadow, [k]: v })}
                />
              ))}
            </div>
          </div>
        </Row>
      </div>
    </Group>
  );
}

/** Two fields side by side, each with its label above, as a design tool sets size beside weight. */
function Pair({ children }: { children: ReactNode }) {
  return <div className="grid grid-cols-2 gap-2">{children}</div>;
}

function Cell({ label, access, children }: { label: string; access: Access; children: ReactNode }) {
  return (
    <div className="flex flex-col gap-1" data-editor-field={label}>
      <span className="flex items-center gap-1 text-xs text-muted-foreground">
        {label}
        {access !== "literal" && <LockMark access={access} />}
      </span>
      {children}
    </div>
  );
}

import { Lock } from "lucide-react";
import { type ReactNode, useEffect, useState } from "react";

import type { ActionResult } from "@uberscene/sdk";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

// Fields the inspector and the typography panel share: each writes on Enter or when it loses focus, not per key.

/** How a prop is written in the file: a literal the editor rewrites, bound to a value the file declares, or code. */
export type Access = "literal" | "bound" | "locked";

/** The reason an action was refused, or null when it went through. */
export const fail = (r: ActionResult | null) =>
  r && !r.ok ? (r.errors?.map((e) => e.message).join("; ") ?? "Refused") : null;

export function Group({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="flex flex-col gap-2">
      <Separator />
      <h4 className="text-xs font-medium text-muted-foreground capitalize">{title}</h4>
      {children}
    </section>
  );
}

export function Row({ label, access = "literal", children }: { label: string; access?: Access; children: ReactNode }) {
  return (
    <div className="grid grid-cols-[6.5rem_1fr] items-center gap-2" data-editor-field={label}>
      <Label className="flex items-center gap-1 truncate text-xs font-normal text-muted-foreground">
        {label}
        {access !== "literal" && <LockMark access={access} />}
      </Label>
      {children}
    </div>
  );
}

/** The lock beside a label: the prop is written as code in the file, or bound to a value it declares. */
export function LockMark({ access }: { access: Access }) {
  const why = access === "locked" ? "Written as code in the file" : "Bound to a value the file declares";
  return (
    <Lock className="size-3 shrink-0" aria-label={why}>
      <title>{why}</title>
    </Lock>
  );
}

/** A number written on Enter or when the field loses focus; Escape puts the value back. */
export function NumberField({
  name,
  value,
  step,
  min,
  max,
  disabled,
  onCommit,
}: {
  name?: string | undefined;
  value: number | undefined;
  step?: number | undefined;
  min?: number | undefined;
  max?: number | undefined;
  disabled?: boolean | undefined;
  onCommit: (v: number) => void;
}) {
  const [draft, setDraft] = useState(value === undefined ? "" : String(value));
  useEffect(() => setDraft(value === undefined ? "" : String(value)), [value]);
  const commit = () => {
    const n = Number(draft);
    if (draft.trim() === "" || !Number.isFinite(n) || n === value)
      return setDraft(value === undefined ? "" : String(value));
    onCommit(n);
  };
  return (
    <Input
      type="number"
      aria-label={name}
      className="h-8 font-mono text-xs"
      value={draft}
      step={step ?? "any"}
      min={min}
      max={max}
      disabled={disabled}
      onChange={(e) => setDraft(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => {
        if (e.key === "Enter") commit();
        if (e.key === "Escape") setDraft(value === undefined ? "" : String(value));
      }}
    />
  );
}

/** Text written on Enter (Cmd/Ctrl+Enter when multiline) or when the field loses focus. */
export function TextField({
  label,
  value,
  multiline,
  swatch,
  disabled,
  onCommit,
}: {
  label: string;
  value: string;
  multiline?: boolean;
  swatch?: boolean;
  disabled?: boolean;
  onCommit: (v: string) => void;
}) {
  const [draft, setDraft] = useState(value);
  useEffect(() => setDraft(value), [value]);
  const commit = () => {
    if (draft !== value) onCommit(draft);
  };
  if (multiline)
    return (
      <Textarea
        aria-label={label}
        value={draft}
        disabled={disabled}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) commit();
        }}
      />
    );
  return (
    <div className="flex items-center gap-2">
      {swatch && (
        <span
          aria-hidden
          className="size-5 shrink-0 rounded border"
          style={{ background: draft.startsWith("$") ? undefined : draft }}
        />
      )}
      <Input
        aria-label={label}
        className="h-8 text-xs"
        value={draft}
        disabled={disabled}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit();
          if (e.key === "Escape") setDraft(value);
        }}
      />
    </div>
  );
}

/**
 * A colour: a swatch that opens the system picker, beside the value as text, which also takes a theme token such as
 * `$primary`. `shown` is what it looks like now (a token resolved, or the default), for the swatch and the placeholder.
 * A pick from the picker is written once the pointer settles, not on every step of the drag.
 */
export function ColorField({
  label,
  value,
  shown,
  disabled,
  onCommit,
}: {
  label: string;
  value: string | undefined;
  shown: string | undefined;
  disabled?: boolean | undefined;
  onCommit: (v: string | undefined) => void;
}) {
  const [draft, setDraft] = useState(value ?? "");
  useEffect(() => setDraft(value ?? ""), [value]);
  const [timer, setTimer] = useState<ReturnType<typeof setTimeout> | null>(null);
  const commit = (next: string) => {
    const v = next.trim() === "" ? undefined : next.trim();
    if (v !== value) onCommit(v);
  };
  const swatch = /^#[0-9a-f]{6}$/i.test(shown ?? "") ? (shown as string) : "#000000";
  return (
    <div className="flex items-center gap-2">
      <label
        className={cn(
          "relative size-8 shrink-0 cursor-pointer overflow-hidden rounded-md border",
          disabled && "pointer-events-none opacity-50",
        )}
        style={{ background: shown }}
      >
        <span className="sr-only">{`${label} picker`}</span>
        <input
          type="color"
          className="absolute inset-0 cursor-pointer opacity-0"
          value={swatch}
          disabled={disabled}
          onChange={(e) => {
            const next = e.target.value;
            setDraft(next);
            if (timer) clearTimeout(timer);
            setTimer(setTimeout(() => commit(next), 300));
          }}
        />
      </label>
      <Input
        aria-label={label}
        className="h-8 font-mono text-xs"
        value={draft}
        placeholder={shown ?? "None"}
        disabled={disabled}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={() => commit(draft)}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit(draft);
          if (e.key === "Escape") setDraft(value ?? "");
        }}
      />
    </div>
  );
}
